-- =========================================================
-- Nihongo — Kanji module seed, batch 5
-- Adds 2 radical-grouped levels (15 kanji, workbook numbers
-- 294–308) on top of seed_kanji_batch4.sql, bringing the module to
-- 213 kanji total. GENERATED by scripts/generate_kanji_batch5_seed.mjs
-- from supabase/data/kanji-294-308.json — edit those, not this file.
--
-- Examples carry an optional "red": true flag = priority (tested)
-- vocabulary; absent = secondary word. Idempotent: each level is
-- created only if missing, its cards seeded only if it has none.
--
-- The aggregate level (order_index 98, "All kanji - Review") is virtual
-- and pools cards at request time, so these levels join it automatically.
-- =========================================================

with m as (select id from modules where slug = 'kanji')
insert into module_levels (module_id, name, order_index, script)
select m.id, lv_name, lv_order, 'none' from m
cross join (values
  ('Hand (手)', 24),
  ('Hand actions (扌・寸・殳・攵)', 25)
) as v(lv_name, lv_order)
where not exists (
  select 1 from module_levels lv
  where lv.module_id = (select id from m) and lv.name = lv_name
);

-- ─── Level 24 — Hand (手) (5) ────────
with lv as (
  select lv.id from module_levels lv
  join modules m on m.id = lv.module_id
  where m.slug = 'kanji' and lv.name = 'Hand (手)'
),
do_seed as (select id from lv where not exists (select 1 from cards c where c.level_id = lv.id))
insert into cards (level_id, fields)
select ds.id, fld::jsonb from do_seed ds
cross join (values
  ('{"kanji":"友","meanings":["friend"],"kunyomi":["とも"],"onyomi":["ゆう"],"card_type":"kanji_flashcard","examples":[{"word":"友達","reading":"ともだち","meaning":"friend","red":true},{"word":"友人","reading":"ゆうじん","meaning":"friend","red":true},{"word":"親友","reading":"しんゆう","meaning":"good friend"}]}'),
  ('{"kanji":"有","meanings":["to have","to exist"],"kunyomi":["あ.る"],"onyomi":["ゆう"],"card_type":"kanji_flashcard","examples":[{"word":"有る","reading":"ある","meaning":"to exist, to have"},{"word":"有名","reading":"ゆうめい","meaning":"famous","red":true},{"word":"有料","reading":"ゆうりょう","meaning":"charge, toll","red":true}]}'),
  ('{"kanji":"反","meanings":["opposite","anti-"],"kunyomi":["そ.る","そ.らす"],"onyomi":["はん"],"card_type":"kanji_flashcard","examples":[{"word":"体を反らす","reading":"からだをそらす","meaning":"to bend backward","red":true},{"word":"反対","reading":"はんたい","meaning":"the opposite","red":true},{"word":"反省する","reading":"はんせいする","meaning":"to reflect on","red":true}]}'),
  ('{"kanji":"取","meanings":["to take"],"kunyomi":["と.る"],"onyomi":["しゅ"],"card_type":"kanji_flashcard","examples":[{"word":"取る","reading":"とる","meaning":"to get, to take","red":true},{"word":"取得する","reading":"しゅとくする","meaning":"to acquire","red":true},{"word":"取材する","reading":"しゅざいする","meaning":"to gather material, to cover (a story)"}]}'),
  ('{"kanji":"受","meanings":["to receive"],"kunyomi":["う.かる","う.ける"],"onyomi":["じゅ"],"card_type":"kanji_flashcard","examples":[{"word":"受かる","reading":"うかる","meaning":"to pass the test","red":true},{"word":"受ける","reading":"うける","meaning":"to receive, to get","red":true},{"word":"受付","reading":"うけつけ","meaning":"reception","red":true},{"word":"受験する","reading":"じゅけんする","meaning":"to take an examination","red":true},{"word":"受信する","reading":"じゅしんする","meaning":"to receive"}]}')
) as v(fld);

-- ─── Level 25 — Hand actions (扌・寸・殳・攵) (10) ────────
with lv as (
  select lv.id from module_levels lv
  join modules m on m.id = lv.module_id
  where m.slug = 'kanji' and lv.name = 'Hand actions (扌・寸・殳・攵)'
),
do_seed as (select id from lv where not exists (select 1 from cards c where c.level_id = lv.id))
insert into cards (level_id, fields)
select ds.id, fld::jsonb from do_seed ds
cross join (values
  ('{"kanji":"持","meanings":["to hold","to have"],"kunyomi":["も.つ"],"onyomi":["じ"],"card_type":"kanji_flashcard","examples":[{"word":"持つ","reading":"もつ","meaning":"to hold, to own","red":true},{"word":"気持ち","reading":"きもち","meaning":"feeling","red":true},{"word":"持参する","reading":"じさんする","meaning":"to bring, to take","red":true}]}'),
  ('{"kanji":"折","meanings":["to fold","to break"],"kunyomi":["お.る","お.れる","おり"],"onyomi":["せつ"],"card_type":"kanji_flashcard","examples":[{"word":"折れる","reading":"おれる","meaning":"to be folded, to be broken","red":true},{"word":"折る","reading":"おる","meaning":"to fold, to break","red":true},{"word":"骨折する","reading":"こっせつする","meaning":"to break a bone","red":true},{"word":"右折する","reading":"うせつする","meaning":"to turn right"}]}'),
  ('{"kanji":"授","meanings":["to grant","to teach"],"kunyomi":["さず.かる","さず.ける"],"onyomi":["じゅ"],"card_type":"kanji_flashcard","examples":[{"word":"授かる","reading":"さずかる","meaning":"to be gifted with, to be awarded"},{"word":"授ける","reading":"さずける","meaning":"to grant, to initiate"},{"word":"授業","reading":"じゅぎょう","meaning":"lesson, class","red":true}]}'),
  ('{"kanji":"捨","meanings":["to throw away"],"kunyomi":["す.てる"],"onyomi":["しゃ"],"card_type":"kanji_flashcard","examples":[{"word":"捨てる","reading":"すてる","meaning":"to throw away","red":true},{"word":"四捨五入","reading":"ししゃごにゅう","meaning":"to round off a fraction"}]}'),
  ('{"kanji":"拾","meanings":["to pick up"],"kunyomi":["ひろ.う"],"onyomi":["しゅう","じゅう"],"card_type":"kanji_flashcard","examples":[{"word":"拾う","reading":"ひろう","meaning":"to pick up, to gather","red":true},{"word":"拾得物","reading":"しゅうとくぶつ","meaning":"something found"}]}'),
  ('{"kanji":"指","meanings":["finger","to point"],"kunyomi":["ゆび","さ.す"],"onyomi":["し"],"card_type":"kanji_flashcard","examples":[{"word":"指","reading":"ゆび","meaning":"finger","red":true},{"word":"指す","reading":"さす","meaning":"to point at","red":true},{"word":"指定席","reading":"していせき","meaning":"reserved seat","red":true},{"word":"指名する","reading":"しめいする","meaning":"to nominate, to designate","red":true}]}'),
  ('{"kanji":"寺","meanings":["temple"],"kunyomi":["てら"],"onyomi":["じ"],"card_type":"kanji_flashcard","examples":[{"word":"寺","reading":"てら","meaning":"temple","red":true},{"word":"東大寺","reading":"とうだいじ","meaning":"Todaiji Temple","red":true}]}'),
  ('{"kanji":"段","meanings":["step","stairs"],"kunyomi":[],"onyomi":["だん"],"card_type":"kanji_flashcard","examples":[{"word":"階段","reading":"かいだん","meaning":"stairs","red":true},{"word":"手段","reading":"しゅだん","meaning":"means","red":true}]}'),
  ('{"kanji":"投","meanings":["to throw"],"kunyomi":["な.げる"],"onyomi":["とう"],"card_type":"kanji_flashcard","examples":[{"word":"投げる","reading":"なげる","meaning":"to throw","red":true},{"word":"投手","reading":"とうしゅ","meaning":"pitcher","red":true}]}'),
  ('{"kanji":"放","meanings":["to release","to set free"],"kunyomi":["はな.す"],"onyomi":["ほう"],"card_type":"kanji_flashcard","examples":[{"word":"放す","reading":"はなす","meaning":"to set free","red":true},{"word":"放送する","reading":"ほうそうする","meaning":"to broadcast","red":true}]}')
) as v(fld);

-- =========================================================
-- Module description bump (198 → 213 kanji)
-- =========================================================
update modules
set description = 'Learn the 213 basic kanji — readings, meanings, and writing.'
where slug = 'kanji';

-- =========================================================
-- Sanity check
-- =========================================================
select lv.order_index, lv.name, count(c.id) as cards
from module_levels lv
join modules m on m.id = lv.module_id
left join cards c on c.level_id = lv.id
where m.slug = 'kanji'
group by lv.order_index, lv.name
order by lv.order_index;
